package com.alpharip.staffmod.AuditFindingsBoard; public final class AuditFindingsSummary {private final int total,open,inReview,actionRequired,resolved,closed,critical,overdue,unfinishedActions;public AuditFindingsSummary(int t,int o,int r,int a,int rs,int c,int cr,int d,int u){total=t;open=o;inReview=r;actionRequired=a;resolved=rs;closed=c;critical=cr;overdue=d;unfinishedActions=u;}public int getTotal(){return total;}public int getOpen(){return open;}public int getInReview(){return inReview;}public int getActionRequired(){return actionRequired;}public int getResolved(){return resolved;}public int getClosed(){return closed;}public int getCritical(){return critical;}public int getOverdue(){return overdue;}public int getUnfinishedActions(){return unfinishedActions;} }
